import { readSourcePresentation } from '../storage/library/sourcePresentation';
import fs from 'fs/promises';
import { nestedFreshSessionWorkdirs } from './historyRoots';
import fsSync from 'fs';
import path from 'path';
import { randomUUID } from 'crypto';
import {
  acquireStartLock,
  readHandshakeResult,
  isServerStartInProgress,
  type StartLock,
} from '../cli/serverHandshake';
import { isPidAlive } from '../utils/pid';
import { TreeStore } from './TreeStore';
import { ProjectStorage } from './ProjectStorage';
import type {
  VariantHistoryManifest,
  VariantHistorySessionFile,
} from './VariantHistoryService';
import { BundleMetadataStore } from '../storage/library/BundleMetadataStore';
import type { ProjectRegistry } from './ProjectRegistry';
import {
  copySourceFiles,
  relocateContext,
  readSourceManifests,
  sourceFingerprint,
  verifyArtifactFile,
} from '../library/importFiles';
import { isPathStrictlyInsideRoot } from '../utils/pathContainment';

interface ImportOptions {
  registry: ProjectRegistry;
  projectId: string;
}
export type ProjectImportResult = {
  status: 'imported' | 'current' | 'deferred' | 'diverged';
  reason?: string;
};
const RECEIPT_FILENAME = 'import-receipt.json';
const RUNTIME_CHANNELS = ['production', 'local'] as const;

const sourceCanWrite = async (
  projectPath: string,
  channel: (typeof RUNTIME_CHANNELS)[number],
): Promise<boolean> => {
  const discovery = readHandshakeResult(projectPath, channel);
  if (discovery.status === 'invalid') return true;
  if (discovery.status === 'found' && isPidAlive(discovery.handshake.pid))
    return true;
  return isServerStartInProgress(projectPath, channel);
};

const verifyImportedVariant = async ({
  manifest,
  artifactRoot,
  trees,
  projectPath,
}: {
  manifest: VariantHistoryManifest;
  artifactRoot: string;
  trees: TreeStore;
  projectPath: string;
}): Promise<void> => {
  if (manifest.artifact.kind === 'diff')
    await verifyArtifactFile(artifactRoot, manifest.artifact.diffPath);
  if (
    manifest.artifact.filesPath &&
    !(
      await fs.stat(path.join(artifactRoot, manifest.artifact.filesPath))
    ).isDirectory()
  )
    throw new Error('Missing saved files');
  if (manifest.preview.kind === 'static')
    await verifyArtifactFile(
      artifactRoot,
      path.join(manifest.preview.rootPath, manifest.preview.entryPath),
    );
  for (const pointer of [manifest.tree, manifest.base, manifest.parent]) {
    if (!pointer) continue;
    const resolved = await trees.resolveRef(projectPath, pointer.commitSha);
    if (
      !resolved ||
      ('treeSha' in pointer && pointer.treeSha !== resolved.treeSha)
    )
      throw new Error(`Missing snapshot: ${pointer.commitSha}`);
    await trees.retainSnapshot(projectPath, pointer.commitSha);
  }
  if (manifest.tree && manifest.serve?.kind === 'static') {
    const extracted = await trees.extractToCache({
      projectPath,
      treeSha: manifest.tree.treeSha,
      commitish: manifest.tree.commitSha,
    });
    await verifyArtifactFile(extracted, manifest.serve.entryPath);
  }
};

export const importProject = async ({
  registry,
  projectId,
}: ImportOptions): Promise<ProjectImportResult> => {
  const project = registry.get(projectId);
  const source = path.join(project.projectPath, '.rivet');
  const nestedRoots = nestedFreshSessionWorkdirs(project.projectPath);
  if (nestedRoots.length > 0) {
    for (const projectPath of nestedRoots)
      registry.attachHistoryRoot({ projectId, projectPath });
    return {
      status: 'deferred',
      reason:
        'This workspace contains nested project histories; they remain readable in their original locations',
    };
  }
  if (!project.isAvailable)
    return {
      status: project.storageKind === 'bundle' ? 'current' : 'deferred',
      reason: 'Workspace is unavailable',
    };
  if (
    (
      await Promise.all(
        RUNTIME_CHANNELS.map((channel) =>
          sourceCanWrite(project.projectPath, channel),
        ),
      )
    ).some(Boolean)
  )
    return {
      status: 'deferred',
      reason: 'A source runtime or opener may still write history',
    };
  const locks: StartLock[] = [];
  try {
    for (const channel of RUNTIME_CHANNELS) {
      const lock = await acquireStartLock(project.projectPath, channel);
      if (!lock) {
        return {
          status: 'deferred',
          reason: 'A project opener holds the startup lock',
        };
      }
      locks.push(lock);
    }
    const hasWriter = RUNTIME_CHANNELS.some((channel) => {
      const discovery = readHandshakeResult(project.projectPath, channel);
      return (
        discovery.status === 'invalid' ||
        (discovery.status === 'found' && isPidAlive(discovery.handshake.pid))
      );
    });
    if (hasWriter)
      return { status: 'deferred', reason: 'Source runtime became available' };
    const fingerprint = await sourceFingerprint(source);
    if (project.storageKind === 'bundle') {
      return {
        status:
          project.sourceFingerprint === fingerprint ? 'current' : 'diverged',
      };
    }
    const destination = registry.bundleDirectory(projectId);
    if (fsSync.existsSync(destination)) {
      const receipt = JSON.parse(
        await fs.readFile(path.join(destination, RECEIPT_FILENAME), 'utf8'),
      );
      if (
        receipt.projectId !== projectId ||
        receipt.sourceFingerprint !== fingerprint
      )
        return {
          status: 'diverged',
          reason: 'An unpublished bundle differs from this source',
        };
      const metadata = await BundleMetadataStore.open({
        directory: destination,
        project,
      });
      try {
        const trees = new TreeStore(
          new ProjectStorage([
            {
              projectPath: project.projectPath,
              dataDirectory: destination,
              cacheDirectory: path.join(registry.root, 'cache', projectId),
            },
          ]),
        );
        const manifests = metadata.listVariants();
        if (manifests.length !== (await readSourceManifests(source)).length)
          throw new Error('Incomplete published bundle');
        for (const manifest of manifests) {
          const relative = metadata.artifactPath(
            manifest.sessionId,
            manifest.variantId,
          );
          if (!relative) throw new Error('Missing imported artifact path');
          const artifactRoot = path.resolve(destination, relative);
          if (!isPathStrictlyInsideRoot(destination, artifactRoot))
            throw new Error('Artifact escapes bundle');
          await verifyImportedVariant({
            manifest,
            artifactRoot,
            trees,
            projectPath: project.projectPath,
          });
        }
      } finally {
        metadata.close();
      }
      registry.activateBundle({ projectId, sourceFingerprint: fingerprint });
      return { status: 'imported' };
    }
    const stage = path.join(
      registry.root,
      'staging',
      `${projectId}-${randomUUID()}`,
    );
    await fs.mkdir(stage, { recursive: true });
    let metadata: BundleMetadataStore | undefined;
    try {
      const manifests = await readSourceManifests(source);
      const presentation = await readSourcePresentation(source);
      await copySourceFiles(source, stage);
      await relocateContext({
        sourceDirectory: source,
        stageDirectory: stage,
        bundleDirectory: destination,
      });
      metadata = await BundleMetadataStore.open({ directory: stage, project });
      const trees = new TreeStore(
        new ProjectStorage([
          {
            projectPath: project.projectPath,
            dataDirectory: stage,
            cacheDirectory: path.join(registry.root, 'cache', projectId),
          },
        ]),
      );
      if (trees.hasStore(project.projectPath))
        await trees.fsck(project.projectPath);
      for (const manifest of manifests) {
        const relative = path.join(
          'variants',
          manifest.sessionId,
          manifest.variantId,
        );
        const artifactRoot = path.join(stage, relative);
        await verifyImportedVariant({
          manifest,
          artifactRoot,
          trees,
          projectPath: project.projectPath,
        });
        metadata.upsertVariant(manifest, relative);
      }
      const sessions = new Set(manifests.map((manifest) => manifest.sessionId));
      for (const sessionId of sessions) {
        const sessionPath = path.join(
          stage,
          'variants',
          sessionId,
          'session.json',
        );
        if (!fsSync.existsSync(sessionPath)) continue;
        const session = JSON.parse(
          await fs.readFile(sessionPath, 'utf8'),
        ) as VariantHistorySessionFile;
        if (session.schemaVersion !== 2 || session.sessionId !== sessionId)
          throw new Error('Unsupported session metadata');
        metadata.putSession(session);
      }
      if (presentation !== null)
        metadata.setPresentation(JSON.parse(presentation));
      if (metadata.listVariants().length !== manifests.length)
        throw new Error('Imported history count does not match source');
      metadata.close();
      metadata = undefined;
      if ((await sourceFingerprint(source)) !== fingerprint)
        throw new Error(
          'Source history changed during import; retry after its writer stops',
        );
      await fs.writeFile(
        path.join(stage, RECEIPT_FILENAME),
        JSON.stringify({ projectId, sourceFingerprint: fingerprint }),
        { mode: 0o600 },
      );
      await fs.mkdir(path.dirname(destination), { recursive: true });
      await fs.rename(stage, destination);
      registry.activateBundle({ projectId, sourceFingerprint: fingerprint });
      return { status: 'imported' };
    } catch (error) {
      metadata?.close();
      await fs.rm(stage, { recursive: true, force: true });
      throw error;
    }
  } finally {
    for (const lock of locks) await lock.release();
  }
};
